  ('dubai-united-arab-emirates', '04A', 'Dubai', 'United Arab Emirates', 'The tallest city on Earth', 'live', 'verified', 'kyoto', 'The Gulf', '{"culture","entertainment","adventure","family"}', '{}', '{"essential","comfort","premier"}', null, 'emerging', '{"key_facts":["HELD CONTENT-ONLY: US State L3 Reconsider Travel amid the ongoing 28 Feb 2026 Gulf conflict; L3 consent gate NOT built - not bookable","Airspace/flights subject to short-notice closures (renewed UAE restrictions 4-11 May 2026); AA cancelled Philadelphia-Doha through end-2026","Marquee sights (planning only): Burj Khalifa, Dubai Mall/Fountain, Museum of the Future, Al Fahidi + Creek abra, desert dune safari","Event flag: 2026 Bahrain + Saudi F1 GPs CANCELLED (F1/FIA 15 Mar 2026) due to the conflict; verify Abu Dhabi GP 2026 status","Advisory + conflict supplied by Strategy Claude (2026-08-09 read); conflict corroborated 2026-08-10 via F1/FIA cancellation coverage; RE-VERIFY before travel"],"safety":{"emergency":"999 police / 998 ambulance (verify)","hospital":"major hospitals in Dubai (verify)","hyperbaric":"not applicable (not a dive destination)","advisory_level":"L3","regional_conflict":"Armed conflict began 28 Feb 2026 (US/Israeli strikes on Iran; Iranian retaliatory strikes on all six GCC states; Hormuz closed; State depart-now for 16 countries 2 Mar 2026); ongoing as of 2026-08-10","no_fly_after_diving":"n/a","malaria":"none (verify)","yellow_fever":"only if arriving from an endemic country","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/united-arab-emirates","read":"2026-08-19","page_updated":"2026-07-24T15:52:23+01:00"}},"timing":{"peak":"Nov-Mar (cool/dry, event season incl. Shopping Festival Jan-Feb) - planning only","shoulder":"Apr & Oct","green":"Jun-Sep (40C+ heat)","booking_lead":"N/A while held content-only (L3, consent gate not built)","off_season_specials":"n/a while held","event_peaks":"Dubai Shopping Festival Jan-Feb; Gulf event circuit","campaign_start":"none while held; re-evaluate on de-escalation + consent gate"},"jewels":[{"name":"Burj Khalifa","si_tag":"culture","status":"future","tier":"premier","hook":"the world''s tallest building; observation decks over Downtown","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"culture","blurb":"the world''s tallest building; observation decks over Downtown","when":"Nov-Mar","commission":"held - ticket/experience affiliate when the consent gate exists"},{"name":"The Dubai Mall & Dubai Fountain","si_tag":"entertainment","status":"future","tier":"comfort","hook":"flagship mall and the choreographed fountain","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"flagship mall and the choreographed fountain","when":"Nov-Mar","commission":"held"},{"name":"Museum of the Future","si_tag":"culture","status":"future","tier":"premier","hook":"the calligraphy-clad future museum","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"the calligraphy-clad future museum","when":"year-round","commission":"held"},{"name":"Al Fahidi (Bastakia) old quarter","si_tag":"culture","status":"future","tier":"comfort","hook":"preserved merchant-heritage district","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"preserved merchant-heritage district","when":"year-round","commission":"held"},{"name":"Dubai Creek abra crossing + Gold Souk","si_tag":"culture","status":"future","tier":"essential","hook":"the traditional ferry crossing and the gold market","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"year-round","timing_type":"ALWAYS-ON","si":"culture","blurb":"the traditional ferry crossing and the gold market","when":"year-round","commission":"held"},{"name":"Dubai Frame","si_tag":"entertainment","status":"future","tier":"comfort","hook":"the giant frame between old and new Dubai","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"the giant frame between old and new Dubai","when":"Nov-Mar","commission":"held"},{"name":"Global Village","si_tag":"entertainment","status":"future","tier":"comfort","hook":"seasonal cultural pavilions and entertainment","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"seasonal cultural pavilions and entertainment","when":"Nov-Mar","commission":"held"},{"name":"Dubai Shopping Festival (Jan-Feb)","si_tag":"entertainment","status":"future","tier":"comfort","hook":"the annual retail-and-entertainment event","bookable_category":"event (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"the annual retail-and-entertainment event","when":"Nov-Mar","commission":"held"},{"name":"Jumeirah Beach & Burj Al Arab strip","si_tag":"family","status":"future","tier":"premier","hook":"the beach strip past the sail-shaped hotel","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","si":"family","blurb":"the beach strip past the sail-shaped hotel","commission":"held"},{"name":"Palm Jumeirah & Atlantis","si_tag":"family","status":"future","tier":"premier","hook":"the palm island and its resort/waterpark","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"family","blurb":"the palm island and its resort/waterpark","when":"Nov-Mar","commission":"held"},{"name":"Dubai Marina","si_tag":"entertainment","status":"future","tier":"comfort","hook":"the skyscraper-and-yacht waterfront","bookable_category":"attraction (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"entertainment","blurb":"the skyscraper-and-yacht waterfront","when":"Nov-Mar","commission":"held"},{"name":"Desert dune safari + Bedouin camp","si_tag":"globaladv","status":"future","tier":"premier","hook":"dune drive, sunset and camp dinner in the desert","bookable_category":"experience (held)","source":"https://en.wikivoyage.org/wiki/Dubai","timing":"Nov-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"adventure","blurb":"dune drive, sunset and camp dinner in the desert","when":"Nov-Mar","commission":"held - DMC/experience when the gate exists"}],"faq":[{"q":"What is the current advisory for Dubai, and can I book it through TravelWell?","a":"The UAE is at U.S. State Department Level 3 - Reconsider Travel, and you cannot book Dubai through TravelWell right now. An armed conflict that began 28 February 2026 - U.S. and Israeli strikes on Iran, then Iranian retaliatory missile and drone strikes across all six GCC states, with the Strait of Hormuz effectively closed to commercial shipping and a State ''depart now'' order on 2 March 2026 - is ongoing as of 2026-08-10. TravelWell books Level 3 destinations only through a consent gate, and that gate is not built, so no Gulf destination is bookable today regardless of level. This is fast-moving: re-verify the level and the flight picture before any travel.","source":"level+conflict supplied by Strategy Claude from a 2026-08-09 read of the US Embassy UAE alert 4 Jun 2026 + State-advisory press; conflict corroborated 2026-08-10 via F1/FIA cancellation coverage (Sky Sports/PlanetF1 via web search)","si_tag":"safety"},{"q":"How are flights and airspace affected?","a":"Airports are open but subject to short-notice closures, and there have been renewed UAE airspace restrictions (reported 4-11 May 2026). As a concrete example, American Airlines cancelled its Philadelphia-Doha route through the end of 2026, with a restart targeted for January 2027. Build slack into any itinerary and confirm every segment close to departure.","source":"supplied by Strategy Claude from a 2026-08-09 read","si_tag":"safety"},{"q":"What would a Dubai trip cover once it is bookable again?","a":"The core is Downtown (Burj Khalifa, Dubai Mall, the Fountain), the Museum of the Future, old Dubai at Al Fahidi with a Dubai Creek abra crossing and the Gold Souk, the Jumeirah beach strip past the Burj Al Arab, Palm Jumeirah, and a desert dune-safari evening. The Dubai Shopping Festival (Jan-Feb) is the marquee event window.","source":"en.wikivoyage.org/wiki/Dubai (accessed 2026-08-10)","si_tag":"planning"},{"q":"When is the best time to visit Dubai?","a":"November-March is the cool, dry season and the event peak (including the Shopping Festival); summer (Jun-Sep) is very hot, routinely above 40C. This is planning-only guidance while the destination is held content-only.","source":"en.wikivoyage.org/wiki/Dubai (accessed 2026-08-10)","si_tag":"planning"},{"q":"Is there anything specific to know about safety in the city itself?","a":"Beyond the regional conflict and the airspace risk, Dubai''s own street-crime level is low; the binding constraints right now are the Level 3 advisory, the flight-disruption risk, and the fact that the destination is held content-only. Re-verify the advisory before acting on anything here.","source":"levels supplied by Strategy Claude from a 2026-08-09 read; en.wikivoyage.org/wiki/Dubai (accessed 2026-08-10)","si_tag":"safety"}],"seo":{"meta_title":"Dubai Travel Advisory & Guide (UAE): Level 3, Safety, Sights","meta_description":"Dubai under a U.S. Level 3 advisory amid the 2026 Gulf conflict - the safety picture, flight disruption, and the sights for when travel resumes. Held content-only.","slug":"dubai-uae","primary_keyword":"Dubai travel advisory 2026","long_tail":["Dubai Level 3 Reconsider Travel","Dubai safety 2026","UAE airspace disruption","Dubai Shopping Festival","Burj Khalifa"],"search_language":"ar (restated, not machine-translated)","local_keywords":["دبي","برج خليفة","تحذير السفر دبي"],"hreflang":["en","ar"],"jsonld_type":"TouristDestination","content_freshness":"2026-08-10"},"booking":{"bin":"content_only_L3_consent_gate_not_built","level":"L3","booking_hold":true,"codes":["L3"],"note":"HELD CONTENT-ONLY. US State Level 3 (Reconsider Travel) for the UAE amid an active regional conflict that began 28 Feb 2026 (US/Israeli strikes on Iran; Iranian retaliatory missile/drone strikes on all six GCC states; Strait of Hormuz closed to commercial shipping; State ''depart now'' for 16 countries + non-emergency personnel ordered out 2 Mar 2026), ONGOING as of 2026-08-10. L3 books only through the consent gate, which Sana confirms is NOT built - so not bookable regardless of level. FAST-MOVING: re-verify both State + FCDO before travel. CITATION: level+conflict supplied by Strategy Claude from a 2026-08-09 read of the US Embassy UAE security alert of 4 Jun 2026 + State-advisory press through late Jul 2026; ae.usembassy.gov returned ''Technical Difficulties'' to a 2026-08-10 re-fetch (not re-read directly); conflict corroborated 2026-08-10 via F1/FIA GP-cancellation coverage (Sky Sports/PlanetF1 via web search)."},"si_checklist_25":{"run_date":"2026-08-10","hits":4,"misses":18,"disregarded":3,"note":"Gulf hub built content-only (safety gap); all SIs future while held; spectator/prosports/compsports disregarded"},"sis_present":[{"si":"culture","name":"culture","status":"future"},{"si":"entertainment","name":"entertainment","status":"future"},{"si":"globaladv","name":"adventure","status":"future"},{"si":"family","name":"family","status":"future"}],"ultra":[{"name":"HELD - Downtown/Palm luxury stay + private desert camp + a Gulf event, via the consent gate once built","why_ultra":"would be the ultra pull once the advisory de-escalates and the gate exists; not offered while held","earning":"n/a while held","virtuoso_value_add":"n/a while held","mor":"n/a while held","source":"TWW booking doctrine"}],"source_verified":"2026-08-10","hero":{"query":"Dubai, United Arab Emirates"},"geo":{"lat":25.2,"lng":55.27}}'::jsonb, 0)
