  ('petra-jordan', '04A', 'Petra', 'Jordan', 'The rose-red city carved from stone', 'live', 'verified', 'desertDunes', 'Jordan & the Levant', '{"culture","deepdive","hiking","ultra"}', '{}', '{"essential","comfort","ultra"}', null, 'anchor', '{"key_facts":["A New7Wonder of the World (2007) and UNESCO World Heritage since 1985 - the rose-red Nabataean caravan city","Entered through the Siq gorge to Al-Khazneh (the Treasury), a ~40 m carved facade; plus the Monastery (Ad-Deir) and Petra by Night","582,550 visitors in 2025 (+27% YoY) - a resilient rebound after the 2024 regional downturn (PDTRA)","The Jordan Pass covers Petra entry (1-3 days) + 40+ sites and waives the tourist-visa fee if you stay >=3 nights","US Level 3 Reconsider Travel (escalated March 2026); the Level-4 Do-Not-Travel areas are the Syria/Iraq border strips - Petra is in the south, far from them","Best season March-April & October-November; summer hits ~40C, winter is cold with rain"],"safety":{"emergency":"911 (unified - police / ambulance / civil defense); Tourist Police +962 79 550 5755","hospital":"Wadi Musa clinics + Amman for major referral; carry travel-medical + evac insurance","advisory_level":"L3","activity_note":"L3 Reconsider Travel - disclose prominently. Level-4 areas = Syria/Iraq borders (far north/east); Petra is in the south, far from them. Steep trail (Monastery ~800 steps) + summer heat (~40C) care; carry water; guide for back routes.","fcdo":{"posture":"AREA-RESTRICTED","quotes":[{"form":"against all travel","text":"advises against all travel to within 3km of the border with Syria."},{"form":"against all travel","text":"advises against all travel to Syria."},{"form":"against all travel","text":"advises against all travel to Iraq ."},{"form":"against all travel","text":"advises against all travel to the provinces in Iraq bordering Jordan."},{"form":"against all but essential travel","text":"advises against all but essential travel Aqaba Governate FCDO advises against all but essential travel to Aqaba international airport and seaport."},{"form":"against all but essential travel","text":"advises against all but essential travel to Aqaba international airport and seaport."}],"url":"https://www.gov.uk/foreign-travel-advice/jordan","read":"2026-08-19","page_updated":"2026-07-22T13:47:55+01:00"}},"timing":{"peak":"Mar-Apr & Oct-Nov (clear light, comfortable days); Apr/May/Sep/Oct heaviest crowds","shoulder":"Mar + Nov","green":"Jun-Aug (~40C, early-morning touring, value) + Dec-Feb (cold, rain, possible snow)","booking_lead":"Petra by Night + nearby camps constrained in peak - book well ahead; Jordan Pass online before arrival for visa waiver","off_season_specials":"summer + winter value; pair with Wadi Rum + Dead Sea + Amman","event_peaks":"spring + autumn peak; Petra by Night on select nights","campaign_start":"sell spring/autumn 2-4 mo out; lead EN + GCC (Saudi #1 source) + DE/FR"},"jewels":[{"name":"Petra by Night by candlelight","si_tag":"culture","status":"live","tier":"essential","price_band":"separate ticket","timing":"Mar-Apr & Oct-Nov","draw_rank":1,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"the Siq lit by 1,500 candles to the Treasury — separate ticket, capacity-limited","si":"culture","blurb":"the Siq lit by 1,500 candles to the Treasury — separate ticket, capacity-limited","when":"Mar-Apr & Oct-Nov","commission":"DMC/guide"},{"name":"A Nabataean archaeology day with a licensed guide","si_tag":"deepdive","status":"live","tier":"essential","price_band":"within the tour","timing":"year-round","draw_rank":1,"timing_type":"ALWAYS-ON","hook":"the Siq, Treasury, Royal Tombs, Colonnaded Street, and the water-engineering story most visitors miss","si":"deepdive","blurb":"the Siq, Treasury, Royal Tombs, Colonnaded Street, and the water-engineering story most visitors miss","when":"year-round","commission":"DMC 10-15%"},{"name":"The climb to the Monastery (Ad-Deir)","si_tag":"hiking","status":"live","